import bpy, math
ang=math.radians(32)
def get(n): return bpy.data.objects.get(n)
def delete(n):
    o=get(n)
    if o: bpy.data.objects.remove(o, do_unlink=True)

# 1. Fix roof front slab slope
rf=get('RoofFront')
if rf: rf.rotation_euler=(ang,0,0)
rb=get('RoofBack')
if rb: rb.rotation_euler=(-ang,0,0)

# 2. Remove middle noren panels -> open serving window; raise/shorten outer panels
for n in ['Noren1','Noren2','NorenCircle1','NorenCircle2','NorenDot1','NorenDot2']:
    delete(n)
for i in [0,3]:
    o=get(f'Noren{i}')
    if o: o.scale=(1,1,0.62); o.location.z=2.42
    c=get(f'NorenCircle{i}')
    if c: c.location.z=2.44
    d=get(f'NorenDot{i}')
    if d: d.location.z=2.44

# 3. Move sign to rooftop above ridge, facing front (-Y)
for n,z in [('SignBoard',4.28),('SignFrameT',4.51),('SignFrameB',4.05)]:
    o=get(n)
    if o: o.location=(0,0.30,z)
t=get('SignText')
if t:
    t.location=(0,0.22,4.28)
    t.rotation_euler=(math.radians(90),0,0)
# sign supports
for i,x in enumerate([-0.8,0.8]):
    bpy.ops.mesh.primitive_cylinder_add(vertices=10, radius=0.03, depth=0.45, location=(x,0.34,3.95))
    o=bpy.context.active_object; o.name=f'SignSupport{i}'
    o.data.materials.append(bpy.data.materials['WoodDark'])

# 4. Raise lanterns slightly and move a touch forward
for i in range(3):
    for base in ['Lantern','LanternCap','LanternBase','LanternCord']:
        o=get(f'{base}{i}')
        if o: o.location.z+=0.16; o.location.y=-1.12
    o=get(f'LanternLight{i}')
    if o: o.location.z+=0.16

# 5. Lower, wider main camera so we see under the eave
from mathutils import Vector
def look_at(obj,target):
    obj.rotation_euler=(Vector(target)-obj.location).to_track_quat('-Z','Y').to_euler()
cam=get('CamMain'); cam.location=(4.9,-7.0,3.0); cam.data.lens=38; look_at(cam,(0,0.1,1.65))
camf=get('CamFront'); camf.location=(0,-7.8,2.0); look_at(camf,(0,0.2,1.65))

bpy.ops.wm.save_as_mainfile(filepath=bpy.data.filepath)
result={'roof_front_rot_x': rf.rotation_euler.x if rf else None, 'objects':len(bpy.data.objects)}

import bpy, math, os
def get(n): return bpy.data.objects.get(n)
def gm(n): return bpy.data.materials[n]
def add_mat(o,m):
    if o.data and hasattr(o.data,'materials'): o.data.materials.append(m)
def sphere(name, loc, scale, material, seg=18):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=seg, ring_count=max(8,seg//2), radius=1.0, location=loc)
    o=bpy.context.active_object; o.name=name; o.scale=scale
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True); add_mat(o,material)
    for p in o.data.polygons: p.use_smooth=True
    return o
def lathe(name, loc, profile, material, seg=20):
    verts=[]; faces=[]; rings=[]
    for (r,z) in profile:
        ring=[]
        for i in range(seg):
            a=2*math.pi*i/seg; ring.append(len(verts)); verts.append((r*math.cos(a), r*math.sin(a), z))
        rings.append(ring)
    for k in range(len(rings)-1):
        for i in range(seg):
            faces.append((rings[k][i], rings[k][(i+1)%seg], rings[k+1][(i+1)%seg], rings[k+1][i]))
    def cap(ring,z,flip):
        ci=len(verts); verts.append((0,0,z))
        for i in range(seg):
            faces.append((ci,ring[(i+1)%seg],ring[i]) if flip else (ci,ring[i],ring[(i+1)%seg]))
    if profile[0][0]>0.001: cap(rings[0],profile[0][1],True)
    if profile[-1][0]>0.001: cap(rings[-1],profile[-1][1],False)
    me=bpy.data.meshes.new(name+'Mesh'); me.from_pydata(verts,[],faces); me.update()
    o=bpy.data.objects.new(name,me); bpy.context.scene.collection.objects.link(o); o.location=loc; add_mat(o,material)
    for p in me.polygons: p.use_smooth=True
    return o

# Lantern cords poking through roof: shorten + lower
for i in range(3):
    o=get(f'LanternCord{i}')
    if o: o.scale=(1,1,0.45); o.location.z-=0.10

# Potted plants flanking the booth front
for i,x in enumerate([-2.75,2.75]):
    lathe(f'PlantPot{i}', (x,-1.55,0.18), [(0.001,0),(0.20,0),(0.26,0.10),(0.28,0.34),(0.30,0.40)], gm('BowlRed'), seg=20)
    sphere(f'PlantTop{i}', (x,-1.55,0.78), (0.30,0.30,0.28), gm('Scallion'), seg=16)
    sphere(f'PlantTop{i}b', (x+0.16,-1.50,0.62), (0.20,0.20,0.18), gm('Scallion'), seg=14)
    sphere(f'PlantTop{i}c', (x-0.15,-1.60,0.64), (0.18,0.18,0.16), gm('Teal'), seg=14)

# Front camera check
scene=bpy.context.scene
scene.camera=get('CamFront')
scene.render.filepath=os.path.join(os.getcwd(),'check_front.png')
bpy.ops.render.render(write_still=True)
scene.camera=get('CamMain')
bpy.ops.wm.save_as_mainfile(filepath=bpy.data.filepath)
result={'front':os.path.join(os.getcwd(),'check_front.png')}
